    fills = set()
    for r in range(h):
        for c1 in range(w):
            if grid[r][c1] == background:
                continue
            for c2 in range(c1 + 1, w):
                if grid[r][c2] == grid[r][c1]:
                    fills.update((r, c) for c in range(c1 + 1, c2) if grid[r][c] == background)
    for c in range(w):
        for r1 in range(h):
            if grid[r1][c] == background:
                continue
            for r2 in range(r1 + 1, h):
                if grid[r2][c] == grid[r1][c]:
                    fills.update((r, c) for r in range(r1 + 1, r2) if grid[r][c] == background)
    for r, c in fills:
        out[r][c] = 4
    return out
'''
